package cl.nexbyte.siger.institucional.formulario;
import cl.nexbyte.siger.institucional.robustez.*;import java.nio.file.Path;import java.net.URI;import org.springframework.context.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.core.env.Environment;import org.springframework.scheduling.annotation.Scheduled;
@Configuration @Profile("jdbc-reception") @ConditionalOnProperty(name="institucional.formulario-completo.habilitado",havingValue="true")
public class FormularioInstitucionalConfiguration {
    @Bean FuenteFormulario fuenteFormulario(Environment e)throws java.io.IOException{var ca=e.getProperty("institucional.formulario-completo.ca-certificado","");return new FuenteFormulario(URI.create(e.getRequiredProperty("institucional.formulario-completo.origen-publico")),e.getRequiredProperty("institucional.formulario-completo.token"),ca.isBlank()?null:Path.of(ca),false);}
    @Bean @ConditionalOnProperty(name="institucional.formulario-completo.exclusivo-qa",havingValue="true") ExclusionConsumidorFormulario exclusionFormulario(BaseJdbc db){return new ExclusionConsumidorFormulario(db);}
    @Bean @DependsOn("validarRuntimeSmr") @ConditionalOnProperty(name="institucional.smr.habilitado",havingValue="true") ExclusionConsumidorFormulario exclusionSmr(BaseJdbc db,Environment e){var uri=URI.create(e.getRequiredProperty("institucional.db.url").substring(5));return new ExclusionConsumidorFormulario(db,uri.getPath().substring(1),e.getProperty("institucional.db.principal",e.getRequiredProperty("institucional.db.user")+"@localhost"),e.getRequiredProperty("institucional.formulario-completo.origen-publico"));}
    @Bean RecuperarFormulario recuperarFormulario(FuenteFormulario s,RecepcionInstitucionalJdbc r,ArchivoInstitucional a,org.springframework.beans.factory.ObjectProvider<ExclusionConsumidorFormulario> exclusion,Environment e){var guard=exclusion.getIfAvailable();boolean smr=e.getProperty("institucional.smr.habilitado",Boolean.class,false);if(smr&&guard==null)throw new IllegalStateException("SMR exige exclusión real");return new RecuperarFormulario(s,r,a,()->{if(smr&&!e.getProperty("institucional.smr.sintetico",Boolean.class,false))cl.nexbyte.siger.institucional.smr.ArranqueSmr.verificarAutorizacion(e);if(guard!=null)guard.verificar();});}
    @Bean @ConditionalOnProperty(name="institucional.formulario-completo.automatico",havingValue="true") Planificador planificadorFormulario(RecuperarFormulario r,ControlesOperacion c){return new Planificador(r,c);}
    public static final class Planificador{
        private final RecuperarFormulario receiver;private final ControlesOperacion control;private final java.util.function.LongSupplier clock;private volatile long next,lastAttempt,lastSuccess,cycles,recovered,confirmed,reconciled;private volatile int failures;private volatile String state="INICIANDO",lastError="";
        Planificador(RecuperarFormulario r,ControlesOperacion c){this(r,c,System::currentTimeMillis);}
        Planificador(RecuperarFormulario r,ControlesOperacion c,java.util.function.LongSupplier clock){receiver=r;control=c;this.clock=clock;}
        @Scheduled(fixedDelayString="${institucional.formulario-completo.intervalo-ms:5000}")public synchronized void tick(){if(clock.getAsLong()<next)return;try{var c=control.estado();if(!c.recuperar()||!c.contingencia().equals("NORMAL")){state="PAUSADO_POR_CONTROL";return;}lastAttempt=clock.getAsLong();cycles++;reconciled+=receiver.conciliar();var r=receiver.ejecutar();recovered+=r.recuperadas();confirmed+=r.confirmadas();if(r.fallidas()>0){lastError="ENTREGA_NO_CONFIRMADA";delay();}else{failures=0;next=0;lastSuccess=clock.getAsLong();lastError="";state=r.recuperadas()==0?"ESPERANDO_ENTREGAS":"RECEPCION_CONFIRMADA";}}catch(RuntimeException e){lastError=e instanceof FalloTecnico f?(f.code==null?"HTTP_"+f.status:f.code):"FALLO_TECNICO";delay();}}
        private void delay(){failures=Math.min(6,failures+1);next=clock.getAsLong()+Math.min(300000,5000L<<failures);state="REINTENTO_PROGRAMADO";}
        public record Estado(boolean automatico,String estado,long ciclos,long ultimoIntentoMs,long ultimoExitoMs,long proximoIntentoMs,int fallosConsecutivos,String ultimoError,long recuperadas,long confirmadas,long conciliadas){}
        public Estado estado(){return new Estado(true,receiver.enCurso()?"RECEPCION_EN_CURSO":state,cycles,lastAttempt,lastSuccess,next,failures,lastError,recovered,confirmed,reconciled);}
    }
}
